import { tags } from "typia";

/**
 * Payment attempt record for an order. Each record logs gateway, status,
 * reference, timestamps, and other audit info. Essential for full payment
 * tracking, fraud prevention, and business analysis. One per attempt, multiple
 * if retries/failures.
 *
 * Fields:
 *
 * - Id: Unique identifier
 * - Payment_reference: Provider or gateway reference
 * - Attempt_status: Payment status ('pending', 'completed', 'failed', etc)
 * - Amount: Amount attempted to charge
 * - Attempted_at: Attempt start
 * - Completed_at: End (nullable)
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingOrderPaymentAttempt = {
  /** Primary key for the payment attempt record. */
  id: string & tags.Format<"uuid">;

  /**
   * External payment provider gateway reference (optional, may be empty until
   * submitted).
   */
  payment_reference?: string | undefined;

  /** Status for this attempt (pending, completed, failed, cancelled). */
  attempt_status: "pending" | "completed" | "failed" | "cancelled";

  /** Total amount attempted to charge in this payment event. */
  amount: number;

  /** Timestamp for attempt creation. */
  attempted_at: string & tags.Format<"date-time">;

  /**
   * When payment attempt finished (success/failure), nullable if still
   * pending.
   */
  completed_at?: (string & tags.Format<"date-time">) | undefined;
};
